const palettes = [["#efcaf5","#cbd0fb","#58e299","#a6b52a","#1c999d","#076390","#3c2500"],
								 ["#cdd7fa","#fac1d6","#65e285","#f68768","#1e9a95","#076587","#42005a"],
								 ["#72f2e3","#7ff299","#76d7f7","#f98da7","#ea6b37","#8043ee","#7b0478","#00193f"],
								 ["#d7d3fb","#fbc3d1","#f7bc6a","#42c5e5","#ed683e","#b41ebc","#07564d","#001b3a"]];

let wormCount = 100, hop; 
let worm = [], dir = [], dest = [], thick= [], anchor=[], bkg;

function setup() {
	createCanvas(windowWidth, windowHeight);
	generate();
}

function mouseClicked() {
	generate();
}

function generate() {
	hop = max(width, height) / 2;
	const tapeWidth = max(width, height) / 60;
	let cent = createVector (width/2,height/2);
	let displace = createVector (cent.mag()*1.1,0);
	let pal = random(palettes);
	if (random()<0.5) {
		bkg = pal[0];
		pal = pal.slice(1)
	} else {
		bkg = pal[pal.length-1];
		pal = pal.slice(0,-1)
	}
	const thickness = (i) => tapeWidth;
	const n = 40;
	const separation = tapeWidth;
	const totalSize = n * separation;
	for (let i = 0; i < wormCount; i++) {
		thick[i] = thickness;
		anchor[i]= floor(random(n));
		worm[i] = new Spine({n, separation, bendMax:radians(random(10,12))});
		worm[i].translate(random(width*0.25,width*0.75-totalSize),height/2);
		dest[i] =createVector(random(width), random(height)); //destiny;//
		dir [i] = createVector(random(0.5,1),0);
		dir [i].rotate(random(TWO_PI))
		worm[i].color = random(pal);
	}
	//noStroke();
	background(bkg);
}

function draw() {
	background(bkg);
	t = frameCount / 100;
	//const newDestiny = random()<0.01? createVector(random(width), random(height)) : null;
	for (let i = 0; i < wormCount; i++) {
		w = worm[i];
		noFill();
		stroke(0);
		strokeWeight(2);
		w.draw(thick[i]);
		fill(w.color);
		noStroke();
		w.draw(thick[i]);
		let p = w.node[anchor[i]];
		let d = p.dist(dest[i]); 
		if (d < 4 || random()<0.01) {
		//if (newDestiny) {
			anchor[i]= floor(random(w.n));
			p = w.node[anchor[i]];
			const delta = createVector (hop,0);
			delta.rotate(random(TWO_PI));
			const newx = constrain(p.x+delta.x,0,width);
			const newy = constrain(p.y+delta.y,0,height);
			dest[i] = createVector (newx,newy); // newDestiny;
		}
		let v = dest[i].copy().sub(p);
		let ang = v.angleBetween(dir[i]);
		dir[i].rotate(constrain(-ang,-PI/90, PI/90));
		let q = p.add(dir[i]);
		w.setNode(anchor[i],q.x,q.y)
	}
}

function arcThickness(n,separation,angle=PI/4) {
	let dAngle = angle*2/(n-1);
	let r = separation * n / 2;
	var p = [];
	let a0 = -PI/2-angle;
	for (let i = 0; i < n; i++) {
		let a = a0 + dAngle*i;
		p.push (r*sin(a))
	}
	return (i) => p[i]-p[0];
}

class Spine {
	constructor ({n=10,separation=20,bendMax=PI/6}={}) {
		let node = [];
		for (let i =0; i<n;i++) node.push(createVector(i*separation,0));
		Object.assign(this,{n,separation,bendMax,node});
	}
	translate (dx,dy) {
		var v = createVector (dx,dy);
		for (let p of this.node) p.add(v);
	}
	relaxRight(i, u) {
		if (i+1 < this.n) { 
			var v = this.node[i+1].copy().sub(this.node[i]);
			// let u = this.node[i].copy().sub(this.node[i-1])
			var ang = u.angleBetween(v);
			if (ang < -this.bendMax) v.rotate(-ang-this.bendMax)
			else if (ang > this.bendMax) v.rotate(-ang+this.bendMax)
			v.setMag(this.separation);
			this.node[i+1] = this.node[i].copy().add(v);
			this.relaxRight(i+1, v)
		}
	}
	relaxLeft(i, u) {
		if (i > 0) { 
			var v = this.node[i-1].copy().sub(this.node[i]);
			//let u = this.node[i].copy().sub(this.node[i+1]);
			var ang = u.angleBetween(v);
			if (ang < -this.bendMax) v.rotate(-ang-this.bendMax)
			else if (ang > this.bendMax) v.rotate(-ang+this.bendMax)
			v.setMag(this.separation);
			this.node[i-1] = this.node[i].copy().add(v);
			this.relaxLeft(i-1,v)
		}
	}
	closest (x,y) {
		let {node,n} = this;
		let best_d = 1e10;
		let best_i = 0;
		var p = createVector(x,y);
		for (let i = 0; i < n; i++) {
			var d = p.dist(node[i]);
			if (d<best_d) {
				best_d = d;
				best_i = i;
			}
		}
		return best_i;
	}
	setNode(i,x,y) {
		let {n,node} = this;
		let u;
		if (i > 0) {
			if (i+1 < n) {
				u = node[i+1].copy().sub(node[i-1]);
			}
			else {
				u = node[i].copy().sub(node[i-1]);
			}
		} 
		else {
			u = node[i+1].copy().sub(node[i]);
		}
		this.node[i] = createVector(x,y);
		this.relaxRight(i,createVector(u.x,u.y));
		this.relaxLeft(i,createVector(-u.x,-u.y));
	}
	draw(thickness=(i)=>10) {
		const {n,node} = this;
		let left = [], right = [];
		for (let i = 0; i < n; i++) {
			var p = i > 0 ? node[i-1] : node[i];
			var q = node[i];
			var r = i < n-1 ? node[i+1] : node[i];
			var v = r.copy().sub(p).setMag(thickness(i)).rotate(PI/2);
			left.push (q.copy().add(v));
			right.push (q.copy().sub(v));
		}
		right.reverse();
		beginShape()
		for (let p of right.slice(-3)) curveVertex (p.x,p.y);
		// let a = left[0];
		// let b = right[0];
		for (let p of left) curveVertex(p.x,p.y);
		for (let p of right) curveVertex(p.x,p.y);
		endShape();
	}
}

